function(container, apiUrl, tables) {
  // 業務ロジックのインポート
  const {
    collectSalesData,
    classifySalesDataByProduct,
    classifySalesDataByStore,
    filterValidProductData,
    collectWeatherData,
    collectEventData,
    collectSeasonalData,
    analyzeCorrelationSalesWeather,
    analyzeCorrelationSalesEvent,
    analyzeCorrelationSalesSeason,
    compareWithHistoricalData,
    findAlternativeComparisonData,
    validateComparisonPeriod
  } = window.aiLogic || {};

  let currentProducts = [];
  let currentForecast = {};

  // エラー表示関数
  function showError(message) {
    window.aivicNotify.error(message);
    const errorDiv = container.querySelector('#error-message');
    if (errorDiv) {
      errorDiv.textContent = message;
      errorDiv.classList.remove('hidden');
      setTimeout(() => errorDiv.classList.add('hidden'), 5000);
    }
  }

  // 成功表示関数
  function showSuccess(message) {
    window.aivicNotify.success(message);
  }

  // バリデーション関数
  function validateInputs() {
    const storeId = container.querySelector('#select-store').value;
    const startDate = container.querySelector('#input-start-date').value;
    const endDate = container.querySelector('#input-end-date').value;

    if (!storeId) {
      showError('店舗を選択してください');
      return false;
    }

    if (!startDate || !endDate) {
      showError('対象期間を設定してください');
      return false;
    }

    // 期間バリデーション（業務ロジック使用）
    if (validateComparisonPeriod) {
      const validation = validateComparisonPeriod(startDate, endDate);
      if (!validation.valid) {
        showError(validation.message);
        return false;
      }
    }

    return true;
  }

  // 数値バリデーション関数
  function validateNumber(value, fieldName, min = 0, max = null) {
    if (value === '' || value === null || value === undefined) return true;

    const num = parseFloat(value);
    if (isNaN(num)) {
      showError(`${fieldName}は数値を入力してください`);
      return false;
    }

    if (num < min) {
      showError(`${fieldName}は${min}以上の値を入力してください`);
      return false;
    }

    if (max !== null && num > max) {
      showError(`${fieldName}は${max}以下の値を入力してください`);
      return false;
    }

    return true;
  }

  // 店舗データ読み込み
  async function loadStores() {
    try {
      const stores = await window.aivicApi.list(1); // 店舗マスタ
      if (!stores) return;

      const select = container.querySelector('#select-store');
      if (!select) return;

      select.innerHTML = '<option value="">店舗を選択してください</option>';

      stores.filter(store => store.有効フラグ).forEach(store => {
        const option = document.createElement('option');
        option.value = store.店舗ID;
        option.textContent = `${store.店舗コード} - ${store.店舗名}`;
        select.appendChild(option);
      });
    } catch (error) {
      showError('店舗データの読み込みに失敗しました');
    }
  }

  // 商品検索・絞り込み
  async function searchProducts() {
    try {
      const keyword = container.querySelector('#input-search')?.value.trim() || '';
      const categoryId = container.querySelector('#select-category')?.value || '';

      const products = await window.aivicApi.list(2); // 商品マスタ
      if (!products) return;

      let filteredProducts = products.filter(product => product.有効フラグ);

      if (keyword) {
        filteredProducts = filteredProducts.filter(product => 
          product.商品名.includes(keyword) || product.商品コード.includes(keyword)
        );
      }

      if (categoryId) {
        filteredProducts = filteredProducts.filter(product => 
          product.カテゴリID === categoryId
        );
      }

      currentProducts = filteredProducts;
      displayProducts(filteredProducts);
    } catch (error) {
      showError('商品検索に失敗しました');
    }
  }

  // 商品一覧表示
  function displayProducts(products) {
    const tbody = container.querySelector('#product-list tbody');
    if (!tbody) return;

    tbody.innerHTML = '';

    products.forEach(product => {
      const row = document.createElement('tr');
      row.innerHTML = `
        <td><input type="checkbox" class="product-checkbox" data-product-id="${product.商品ID}"></td>
        <td>${product.商品コード}</td>
        <td>${product.商品名}</td>
        <td>${product.カテゴリ名 || ''}</td>
        <td>${product.単価 || 0}</td>
        <td>${product.在庫数 || 0}</td>
      `;
      tbody.appendChild(row);
    });
  }

  // 需要予測実行
  async function executeForecast() {
    if (!validateInputs()) return;

    try {
      const storeId = container.querySelector('#select-store').value;
      const startDate = container.querySelector('#input-start-date').value;
      const endDate = container.querySelector('#input-end-date').value;

      // 選択された商品を取得
      const selectedProducts = [];
      container.querySelectorAll('.product-checkbox:checked').forEach(checkbox => {
        const productId = checkbox.dataset.productId;
        const product = currentProducts.find(p => p.商品ID === productId);
        if (product) selectedProducts.push(product);
      });

      if (selectedProducts.length === 0) {
        showError('予測対象の商品を選択してください');
        return;
      }

      // 業務ロジックを使用して予測実行
      const salesData = await collectSalesData(storeId, startDate, endDate);
      const weatherData = await collectWeatherData(startDate, endDate);
      const eventData = await collectEventData(startDate, endDate);
      const seasonalData = await collectSeasonalData(startDate, endDate);

      // 商品別売上データ分類
      const productSalesData = classifySalesDataByProduct(salesData, selectedProducts);

      // 相関分析
      const weatherCorrelation = analyzeCorrelationSalesWeather(productSalesData, weatherData);
      const eventCorrelation = analyzeCorrelationSalesEvent(productSalesData, eventData);
      const seasonCorrelation = analyzeCorrelationSalesSeason(productSalesData, seasonalData);

      // 過去データとの比較
      const historicalComparison = compareWithHistoricalData(productSalesData, startDate, endDate);

      // 予測結果を生成
      const forecastResults = selectedProducts.map(product => {
        const productSales = productSalesData[product.商品ID] || [];
        const avgSales = productSales.reduce((sum, sale) => sum + sale.売上数量, 0) / productSales.length || 0;

        // 各要因の影響を考慮した予測値計算
        let forecastQuantity = avgSales;

        if (weatherCorrelation[product.商品ID]) {
          forecastQuantity *= weatherCorrelation[product.商品ID].影響係数 || 1;
        }

        if (eventCorrelation[product.商品ID]) {
          forecastQuantity *= eventCorrelation[product.商品ID].影響係数 || 1;
        }

        if (seasonCorrelation[product.商品ID]) {
          forecastQuantity *= seasonCorrelation[product.商品ID].影響係数 || 1;
        }

        return {
          商品ID: product.商品ID,
          商品名: product.商品名,
          予測数量: Math.round(forecastQuantity),
          信頼度: calculateConfidence(weatherCorrelation, eventCorrelation, seasonCorrelation, product.商品ID)
        };
      });

      currentForecast = {
        店舗ID: storeId,
        対象期間開始: startDate,
        対象期間終了: endDate,
        予測結果: forecastResults
      };

      displayForecastResults(forecastResults);
      showSuccess('需要予測が完了しました');

    } catch (error) {
      showError('需要予測の実行に失敗しました: ' + error.message);
    }
  }

  // 信頼度計算
  function calculateConfidence(weatherCorr, eventCorr, seasonCorr, productId) {
    let confidence = 0.5; // ベース信頼度

    if (weatherCorr[productId]?.相関係数) {
      confidence += Math.abs(weatherCorr[productId].相関係数) * 0.2;
    }

    if (eventCorr[productId]?.相関係数) {
      confidence += Math.abs(eventCorr[productId].相関係数) * 0.2;
    }

    if (seasonCorr[productId]?.相関係数) {
      confidence += Math.abs(seasonCorr[productId].相関係数) * 0.1;
    }

    return Math.min(confidence, 1.0);
  }

  // 予測結果表示
  function displayForecastResults(results) {
    const tbody = container.querySelector('#forecast-results tbody');
    if (!tbody) return;

    tbody.innerHTML = '';

    results.forEach(result => {
      const row = document.createElement('tr');
      row.innerHTML = `
        <td>${result.商品名}</td>
        <td>${result.予測数量}</td>
        <td>${(result.信頼度 * 100).toFixed(1)}%</td>
        <td>
          <input type="number" class="adjustment-input" data-product-id="${result.商品ID}" 
                 value="${result.予測数量}" min="0" style="width: 80px;">
        </td>
        <td>
          <input type="text" class="memo-input" data-product-id="${result.商品ID}" 
                 placeholder="調整理由" style="width: 150px;">
        </td>
      `;
      tbody.appendChild(row);
    });
  }

  // 発注量計算
  async function calculateOrderQuantity() {
    try {
      if (!currentForecast.予測結果 || currentForecast.予測結果.length === 0) {
        showError('先に需要予測を実行してください');
        return;
      }

      const storeId = currentForecast.店舗ID;
      const orderResults = [];

      for (const forecast of currentForecast.予測結果) {
        // 調整後予測数量を取得
        const adjustmentInput = container.querySelector(`input.adjustment-input[data-product-id="${forecast.商品ID}"]`);
        const adjustedQuantity = adjustmentInput ? parseInt(adjustmentInput.value) || 0 : forecast.予測数量;

        // 調整理由を取得
        const memoInput = container.querySelector(`input.memo-input[data-product-id="${forecast.商品ID}"]`);
        const memo = memoInput ? memoInput.value : '';

        // 現在の在庫数を取得
        const product = currentProducts.find(p => p.商品ID === forecast.商品ID);
        const currentStock = product ? product.在庫数 || 0 : 0;

        // 安全在庫を考慮した発注量計算
        const safetyStock = Math.ceil(adjustedQuantity * 0.2); // 予測数量の20%を安全在庫とする
        const requiredStock = adjustedQuantity + safetyStock;
        const orderQuantity = Math.max(0, requiredStock - currentStock);

        orderResults.push({
          商品ID: forecast.商品ID,
          商品名: forecast.商品名,
          予測数量: forecast.予測数量,
          調整後予測数量: adjustedQuantity,
          現在在庫: currentStock,
          安全在庫: safetyStock,
          発注量: orderQuantity,
          調整理由: memo
        });
      }

      displayOrderResults(orderResults);
      showSuccess('発注量計算が完了しました');

    } catch (error) {
      showError('発注量計算に失敗しました: ' + error.message);
    }
  }

  // 発注量結果表示
  function displayOrderResults(results) {
    const tbody = container.querySelector('#order-results tbody');
    if (!tbody) return;

    tbody.innerHTML = '';

    results.forEach(result => {
      const row = document.createElement('tr');
      row.innerHTML = `
        <td>${result.商品名}</td>
        <td>${result.予測数量}</td>
        <td>${result.調整後予測数量}</td>
        <td>${result.現在在庫}</td>
        <td>${result.安全在庫}</td>
        <td class="order-quantity">${result.発注量}</td>
        <td>${result.調整理由}</td>
      `;
      tbody.appendChild(row);
    });
  }

  // 発注データ保存
  async function saveOrderData() {
    try {
      const orderRows = container.querySelectorAll('#order-results tbody tr');
      if (orderRows.length === 0) {
        showError('保存する発注データがありません');
        return;
      }

      const orderData = [];
      orderRows.forEach((row, index) => {
        const cells = row.querySelectorAll('td');
        const orderQuantity = parseInt(cells[5].textContent) || 0;

        if (orderQuantity > 0) {
          const result = currentForecast.予測結果[index];
          orderData.push({
            店舗ID: currentForecast.店舗ID,
            商品ID: result.商品ID,
            発注数量: orderQuantity,
            予測数量: result.予測数量,
            調整理由: cells[6].textContent,
            作成日時: new Date().toISOString(),
            ステータス: '未発注'
          });
        }
      });

      if (orderData.length === 0) {
        showError('発注量が0より大きい商品がありません');
        return;
      }

      // 発注データを保存
      for (const order of orderData) {
        await window.aivicApi.save(5, order); // 発注データテーブル
      }

      showSuccess(`${orderData.length}件の発注データを保存しました`);

    } catch (error) {
      showError('発注データの保存に失敗しました: ' + error.message);
    }
  }

  // カテゴリデータ読み込み
  async function loadCategories() {
    try {
      const categories = await window.aivicApi.list(3); // カテゴリマスタ
      if (!categories) return;

      const select = container.querySelector('#select-category');
      if (!select) return;

      select.innerHTML = '<option value="">全カテゴリ</option>';

      categories.filter(category => category.有効フラグ).forEach(category => {
        const option = document.createElement('option');
        option.value = category.カテゴリID;
        option.textContent = category.カテゴリ名;
        select.appendChild(option);
      });
    } catch (error) {
      showError('カテゴリデータの読み込みに失敗しました');
    }
  }

  // イベントハンドラー設定
  function setupEventHandlers() {
    // 検索ボタン
    const searchBtn = container.querySelector('#btn-search');
    if (searchBtn) {
      searchBtn.addEventListener('click', searchProducts);
    }

    // 予測実行ボタン
    const forecastBtn = container.querySelector('#btn-forecast');
    if (forecastBtn) {
      forecastBtn.addEventListener('click', executeForecast);
    }

    // 発注量計算ボタン
    const calculateBtn = container.querySelector('#btn-calculate');
    if (calculateBtn) {
      calculateBtn.addEventListener('click', calculateOrderQuantity);
    }

    // 保存ボタン
    const saveBtn = container.querySelector('#btn-save');
    if (saveBtn) {
      saveBtn.addEventListener('click', saveOrderData);
    }

    // 全選択チェックボックス
    const selectAllCheckbox = container.querySelector('#select-all-products');
    if (selectAllCheckbox) {
      selectAllCheckbox.addEventListener('change', function() {
        const checkboxes = container.querySelectorAll('.product-checkbox');
        checkboxes.forEach(checkbox => {
          checkbox.checked = this.checked;
        });
      });
    }

    // 検索フィールドでのEnterキー
    const searchInput = container.querySelector('#input-search');
    if (searchInput) {
      searchInput.addEventListener('keypress', function(e) {
        if (e.key === 'Enter') {
          searchProducts();
        }
      });
    }

    // カテゴリ変更時の自動検索
    const categorySelect = container.querySelector('#select-category');
    if (categorySelect) {
      categorySelect.addEventListener('change', searchProducts);
    }
  }

  // 初期化処理
  async function initialize() {
    try {
      await loadStores();
      await loadCategories();
      setupEventHandlers();

      // デフォルト期間設定（今日から1週間後）
      const today = new Date();
      const nextWeek = new Date(today.getTime() + 7 * 24 * 60 * 60 * 1000);

      const startDateInput = container.querySelector('#input-start-date');
      const endDateInput = container.querySelector('#input-end-date');

      if (startDateInput) {
        startDateInput.value = today.toISOString().split('T')[0];
      }

      if (endDateInput) {
        endDateInput.value = nextWeek.toISOString().split('T')[0];
      }

    } catch (error) {
      showError('画面の初期化に失敗しました');
    }
  }

  // 初期化実行
  initialize();
}
